import {errorResponse,fail} from '@/lib/platform/http';
import {externalJob,externalRespond,externalUpload} from '@/lib/platform/communications';
export const dynamic='force-dynamic';
export async function GET(request:Request){try{const token=new URL(request.url).searchParams.get('token')||'';if(token.length<20)fail(404,'This job link is invalid or has expired.');return Response.json(await externalJob(token),{headers:{'Cache-Control':'private, no-store'}});}catch(e){return errorResponse(e);}}
export async function POST(request:Request){try{const form=await request.formData();const token=String(form.get('token')||'');if(token.length<20)fail(404,'This job link is invalid or has expired.');const file=form.get('file');if(file instanceof File)return Response.json(await externalUpload(token,file),{status:201});const action=String(form.get('action')||'');if(!['accepted','declined','acknowledged','details'].includes(action))fail(400,'Unknown response.');const payload={note:String(form.get('note')||'').slice(0,1000),operator:String(form.get('operator')||'').slice(0,180),plant:String(form.get('plant')||'').slice(0,180)};return Response.json(await externalRespond(token,action as 'accepted'|'declined'|'acknowledged'|'details',payload),{status:201});}catch(e){return errorResponse(e);}}
